"208 :   private Node tryFoldSimpleFunctionCall(Node n) {
209 :     Preconditions.checkState(n.isCall());
210 :     Node callTarget = n.getFirstChild();
211 :     if (callTarget != null && callTarget.isName() &&
212 :           callTarget.getString().equals("String")) {
213 :       // Fold String(a) to '' + (a) on immutable literals,
214 :       // which allows further optimizations
215 :       //
216 :       // We can't do this in the general case, because String(a) has
217 :       // slightly different semantics than '' + (a). See
218 :       // http://code.google.com/p/closure-compiler/issues/detail?id=759
219 :       Node value = callTarget.getNext();
220 :       if (value != null) {
221 :         Node addition = IR.add(
222 :             IR.string("").srcref(callTarget),
223 :             value.detachFromParent());
224 :         n.getParent().replaceChild(n, addition);
225 :         reportCodeChange();
226 :         return addition;
227 :       }
228 :     }
229 :     return n;
230 :   }"

" 75 :   @Override
 76 :   @SuppressWarnings("fallthrough")
 77 :   public Node optimizeSubtree(Node node) {
 78 :     switch(node.getType()) {
 79 :       case Token.RETURN: {
 80 :         Node result = tryRemoveRedundantExit(node);
 81 :         if (result != node) {
 82 :           return result;
 83 :         }
 84 :         result = tryReplaceExitWithBreak(node);
 85 :         if (result != node) {
 86 :           return result;
 87 :         }
 88 :         return tryReduceReturn(node);
 89 :       }
 90 : 
 91 :       case Token.THROW: {
 92 :         Node result = tryRemoveRedundantExit(node);
 93 :         if (result != node) {
 94 :           return result;
 95 :         }
 96 :         return tryReplaceExitWithBreak(node);
 97 :       }
 98 : 
 99 :       // TODO(johnlenz): Maybe remove redundant BREAK and CONTINUE. Overlaps
100 :       // with MinimizeExitPoints.
101 : 
102 :       case Token.NOT:
103 :         tryMinimizeCondition(node.getFirstChild());
104 :         return tryMinimizeNot(node);
105 : 
106 :       case Token.IF:
107 :         tryMinimizeCondition(node.getFirstChild());
108 :         return tryMinimizeIf(node);
109 : 
110 :       case Token.EXPR_RESULT:
111 :         tryMinimizeCondition(node.getFirstChild());
112 :         return node;
113 : 
114 :       case Token.HOOK:
115 :         tryMinimizeCondition(node.getFirstChild());
116 :         return node;
117 : 
118 :       case Token.WHILE:
119 :       case Token.DO:
120 :         tryMinimizeCondition(NodeUtil.getConditionExpression(node));
121 :         return node;
122 : 
123 :       case Token.FOR:
124 :         if (!NodeUtil.isForIn(node)) {
125 :           tryJoinForCondition(node);
126 :           tryMinimizeCondition(NodeUtil.getConditionExpression(node));
127 :         }
128 :         return node;
129 : 
130 :       case Token.TRUE:
131 :       case Token.FALSE:
132 :         return reduceTrueFalse(node);
133 : 
134 :       case Token.NEW:
135 :         node = tryFoldStandardConstructors(node);
136 :         if (!node.isCall()) {
137 :           return node;
138 :         }
139 :         // Fall through on purpose because tryFoldStandardConstructors() may
140 :         // convert a NEW node into a CALL node
141 :       case Token.CALL:
142 :         Node result =  tryFoldLiteralConstructor(node);
143 :         if (result == node) {
144 :           result = tryFoldSimpleFunctionCall(node);
145 :           if (result == node) {
146 :             result = tryFoldImmediateCallToBoundFunction(node);
147 :           }
148 :         }
149 :         return result;
150 : 
151 :       case Token.COMMA:
152 :         return trySplitComma(node);
153 : 
154 :       case Token.NAME:
155 :         return tryReplaceUndefined(node);
156 : 
157 :       case Token.BLOCK:
158 :         return tryReplaceIf(node);
159 : 
160 :       case Token.ARRAYLIT:
161 :         return tryMinimizeArrayLiteral(node);
162 : 
163 :       default:
164 :         return node; //Nothing changed
165 :     }
166 :   }"

"1363 :   private Node tryFoldLiteralConstructor(Node n) {
1364 :     Preconditions.checkArgument(n.isCall()
1365 :         || n.isNew());
1366 : 
1367 :     Node constructorNameNode = n.getFirstChild();
1368 : 
1369 :     Node newLiteralNode = null;
1370 : 
1371 :     // We require the AST to be normalized to ensure that, say,
1372 :     // Object() really refers to the built-in Object constructor
1373 :     // and not a user-defined constructor with the same name.
1374 : 
1375 :     if (isASTNormalized() && Token.NAME == constructorNameNode.getType()) {
1376 : 
1377 :       String className = constructorNameNode.getString();
1378 : 
1379 :       if ("RegExp".equals(className)) {
1380 :         // "RegExp("boo", "g")" --> /boo/g
1381 :         return tryFoldRegularExpressionConstructor(n);
1382 :       } else {
1383 :         boolean constructorHasArgs = constructorNameNode.getNext() != null;
1384 : 
1385 :         if ("Object".equals(className) && !constructorHasArgs) {
1386 :           // "Object()" --> "{}"
1387 :           newLiteralNode = IR.objectlit();
1388 :         } else if ("Array".equals(className)) {
1389 :           // "Array(arg0, arg1, ...)" --> "[arg0, arg1, ...]"
1390 :           Node arg0 = constructorNameNode.getNext();
1391 :           FoldArrayAction action = isSafeToFoldArrayConstructor(arg0);
1392 : 
1393 :           if (action == FoldArrayAction.SAFE_TO_FOLD_WITH_ARGS ||
1394 :               action == FoldArrayAction.SAFE_TO_FOLD_WITHOUT_ARGS) {
1395 :             newLiteralNode = IR.arraylit();
1396 :             n.removeChildren();
1397 :             if (action == FoldArrayAction.SAFE_TO_FOLD_WITH_ARGS) {
1398 :               newLiteralNode.addChildrenToFront(arg0);
1399 :             }
1400 :           }
1401 :         }
1402 : 
1403 :         if (newLiteralNode != null) {
1404 :           n.getParent().replaceChild(n, newLiteralNode);
1405 :           reportCodeChange();
1406 :           return newLiteralNode;
1407 :         }
1408 :       }
1409 :     }
1410 :     return n;
1411 :   }"

